CREATE OR REPLACE FUNCTION public.validate_partner_property_setup() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF NEW.latitude IS NOT NULL AND (NEW.latitude < -90 OR NEW.latitude > 90) THEN RAISE EXCEPTION 'Latitude must be between -90 and 90'; END IF; IF NEW.longitude IS NOT NULL AND (NEW.longitude < -180 OR NEW.longitude > 180) THEN RAISE EXCEPTION 'Longitude must be between -180 and 180'; END IF; IF length(NEW.name)>160 OR length(NEW.description)>5000 OR length(NEW.contact_email)>254 OR length(NEW.address)>500 THEN RAISE EXCEPTION 'Hotel information exceeds allowed length'; END IF; IF NEW.star_rating IS NOT NULL AND (NEW.star_rating<0 OR NEW.star_rating>5) THEN RAISE EXCEPTION 'Star rating must be between 0 and 5'; END IF; IF NEW.type_details IS NOT NULL AND jsonb_typeof(NEW.type_details)<>'object' THEN RAISE EXCEPTION 'Property details must be an object'; END IF; IF NEW.policies IS NOT NULL AND jsonb_typeof(NEW.policies)<>'object' THEN RAISE EXCEPTION 'Policies must be an object'; END IF; RETURN NEW; END $$;
CREATE TRIGGER validate_partner_property_setup BEFORE INSERT OR UPDATE OF name,description,address,contact_email,latitude,longitude,star_rating,type_details,policies ON public.partner_hotels FOR EACH ROW EXECUTE FUNCTION public.validate_partner_property_setup();